**f12 sang tab console**

lam cac buoc sau, nhap r nhan enter

**buoc 1:**  
var ws = new WebSocket("ws://localhost:8080/api/ws-chat-raw");  
ws.onmessage = function(event) { console.log("Server trả về: ", event.data); };

ws.onopen = function() {  
// Gửi lệnh CONNECT chuẩn chỉnh kèm ký tự Null mã máy \\u0000  
var connectFrame = "CONNECT\\naccept-version:1.1,1.2\\nheart-beat:0,0\\n\\n\\u0000";  
ws.send(connectFrame);  
};

**buoc 2:**  
var chatRoomId = "NHAP_ROOMID_TREN_THANH_URL_VAO_DAY";  
var payload = {  
senderId: "6a2a9b54d108d32044bec9bc",  
content: "Chào Bách, mình là An đây! Mình đang nhắn từ Console Trình duyệt nè.",  
timestamp: new Date().toISOString()  
};

var sendFrame = "SEND\\ndestination:/app/chat.sendMessage/" + chatRoomId + "\\ncontent-type:application/json\\n\\n" + JSON.stringify(payload) + "\\u0000";  
ws.send(sendFrame);
